/* ADC sample averaging example – Zephyr RTOS
 *
 * Target board: nrf52840dk/nrf52840
 *
 * This application configures ADC channel 0 with a gain of 1, internal
 * reference, default acquisition time, and performs a 12‑bit conversion
 * with hardware oversampling (2^4 = 16 samples). The averaged result
 * is read and printed once per second.
 */

#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/adc.h>

int main(void)
{
    /* Get the ADC device defined in the devicetree alias */
    const struct device *adc = DEVICE_DT_GET(DT_ALIAS(adc0));

    if (!device_is_ready(adc)) {
        printk("ADC device not ready\n");
        return -ENODEV;
    }

    /* Configure ADC channel 0 */
    struct adc_channel_cfg channel_cfg = {
        .gain              = ADC_GAIN_1,
        .reference         = ADC_REF_INTERNAL,
        .acquisition_time = ADC_ACQ_TIME_DEFAULT,
        .channel_id        = 0,
    };

    int ret = adc_channel_setup(adc, &channel_cfg);
    if (ret) {
        printk("adc_channel_setup failed: %d\n", ret);
        return ret;
    }

    /* Static buffer for one 12‑bit sample */
    static int16_t sample[1] = {0};

    /* ADC sequence configuration */
    struct adc_sequence sequence = {
        .channels     = BIT(0),
        .buffer       = sample,
        .buffer_size  = sizeof(sample),
        .resolution   = 12,
        .oversampling = 4,  /* 2^4 = 16 hardware averaged samples */
    };

    while (1) {
        ret = adc_read(adc, &sequence);
        if (ret) {
            printk("adc_read failed: %d\n", ret);
        } else {
            printk("Raw sample: %d\n", sample[0]);
        }

        k_sleep(K_SECONDS(1));
    }

    return 0; /* Never reached */
}
